window.RP_SESSION={"id":"S-fd42207203ce","messages":[{"id":"RP-II-0083687","time":"2026-04-15T19:04:00+09:00","room":"RP II","name":"사건 서술자","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"참 묘한 일이었다.\n\n이것참 기이한 일이다.\n\n갈디고스 동부의 소마을, 그란벨루크의 외곽에서 이상한 사체가 연이어 세 구 발견되었다.\n\n사체의 혈액은 모두 빠져 창백하고 바짝 말랐고.\n두 눈이 텅 빈 사체 세 구의 등장에 마을 주민들이 공포에 떨었더랬다.\n\n그란벨루크의 사제 미로크 슈엔은 라운데라 정교회로 이 일을 보고했다.\n\n그리고 두 명의 성기사가 이 일의 진상을 밝히기 위해 파견되었다.\n\n외력에 의한 타살이나 타상 및 자상이 없음.\n흑마법의 잔여물이 확인되지 않음.\n정확한 사망 사유 알 수 없음.\n아직까지는.\n\n기이한 일이다.\n\n그것 참 이상한 일이었다.","characters":[]},{"id":"RP-II-0083688","time":"2026-04-15T19:04:00+09:00","room":"RP II","name":"사건 서술자","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0083689","time":"2026-04-15T19:04:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
